'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

function allSplits(text, opts) {
  const whole = parse(text, opts);
  for (let a = 0; a <= text.length; a++) {
    for (let b = a; b <= text.length; b++) {
      const p = createParser(opts);
      const out = [];
      for (const c of [text.slice(0, a), '', text.slice(a, b), text.slice(b)]) {
        const got = p.push(c);
        out.push(...got);
      }
      out.push(...p.end());
      assert.deepEqual(out, whole, JSON.stringify({ text, a, b }));
    }
  }
  return whole;
}

const cases = [
  ['', []],
  ['\uFEFF', []],
  ['\n', [['']]],
  ['\n\n', [[''], ['']]],
  ['a\n', [['a']]],
  ['a\r\nb\rc\n', [['a'], ['b'], ['c']]],
  ['\r\n\r\n', [[''], ['']]],
  ['\r\r', [[''], ['']]],
  ['\uFEFFa,\uFEFFb', [['a', '\uFEFFb']]],
  ['a"b,c"', [['a"b', 'c"']]],
  ['"x""y",""', [['x"y', '']]],
  ['"a\r\nb\rc\nd",e\r\n', [['a\r\nb\rc\nd', 'e']]],
  ['""', [['']]],
  [',', [['', '']]],
  ['"a"\r\n"b"', [['a'], ['b']]],
  ['\uD83D\uDE00,x', [['\uD83D\uDE00', 'x']]],
];
for (const [text, expected] of cases) assert.deepEqual(allSplits(text), expected, JSON.stringify(text));
assert.deepEqual(allSplits('a;"b;c"\nd', { delimiter: ';' }), [['a', 'b;c'], ['d']]);
assert.deepEqual(allSplits('a\tb', { delimiter: '\t' }), [['a', 'b']]);

// Immediate emission, including CR before LF arrives.
let p = createParser();
assert.deepEqual(p.push('a,b\r'), [['a', 'b']]);
assert.deepEqual(p.push('\nc'), []);
assert.deepEqual(p.push('\r'), [['c']]);
assert.deepEqual(p.end(), []);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), e => e instanceof Error);

// BOM only at very start; empty chunk before BOM ok.
p = createParser();
p.push('');
assert.deepEqual(p.push('\uFEFFa\n'), [['a']]);
p = createParser();
p.push('a');
assert.deepEqual(p.push('\uFEFF\n'), [['a\uFEFF']]);

// Line numbers.
function lineOf(chunks) {
  const q = createParser();
  try { for (const c of chunks) q.push(c); q.end(); } catch (e) {
    assert.ok(e instanceof SyntaxError, String(e));
    return Number(/line (\d+)/.exec(e.message)[1]);
  }
  throw new Error('no error');
}
assert.equal(lineOf(['"a" ,b']), 1);
assert.equal(lineOf(['x\n"a"x']), 2);
assert.equal(lineOf(['"a\r', '\nb"x']), 2);
assert.equal(lineOf(['"a\r\n\r\n\rb\n"x']), 5);
assert.equal(lineOf(['a\r', '\n\r', '\n"b"c']), 3);
assert.equal(lineOf(['a\n"unterminated\r\n']), 3);
assert.equal(lineOf(['"']), 1);
assert.equal(lineOf(['"a"', '"', 'b"c']), 1);

// Validation.
for (const d of ['"', '\r', '\n', '', ',,', 1, null, '\uD83D\uDE00']) {
  assert.throws(() => createParser({ delimiter: d }), RangeError, String(d));
}
assert.deepEqual(createParser({ delimiter: undefined }).push('a,b\n'), [['a', 'b']]);
assert.throws(() => createParser().push(1), TypeError);
assert.throws(() => createParser().push(undefined), TypeError);

// Independent state.
const p1 = createParser(); const p2 = createParser();
p1.push('"a'); assert.deepEqual(p2.push('b\n'), [['b']]);

// Header mode.
assert.deepEqual(parse('', { header: true }), []);
assert.deepEqual(parse('x,x,x_2,x\n1,2,3,4', { header: true }), [{ x: '1', x_2: '2', x_2_2: '3', x_3: '4' }]);
const o = parse('__proto__,b\n1', { header: true })[0];
assert.equal(Object.getPrototypeOf(o), Object.prototype);
assert.deepEqual(Object.keys(o), ['__proto__', 'b']);
assert.equal(o.b, '');
assert.deepEqual(createParser({ header: true }).push('a\n'), [['a']]);
console.log('all checks passed');

